"""Create ordered call tables from completed actors; no experiment changes."""
import csv,json,hashlib,math
from pathlib import Path
R=Path('/mnt/data/physical-RSI/result/31_rgb_supplement_20261105');A=R/'analysis'
d=json.loads((A/'matrix-analysis.json').read_text());rows=[]
for actor in d['actors']:
    path=R/actor['process_record'];p=json.loads(path.read_text())
    for call in sorted(p['calls'],key=lambda c:c['request']['id']):
        response=call.get('response',{});value=response.get('value',{})
        row=dict(condition=actor['condition'],layout_id=actor['mapped_layout_id'],mapping_qualified=actor['mapping_qualified'],actor_episode_id=actor['actor_episode_id'],call_id=call['request']['id'],method=call['request']['method'],state=call['state'],response_present='response' in call,arguments=call['request'].get('kwargs',{}),primitive_error=value.get('primitive_error'),scene_observation_sequence=value.get('observation',{}).get('sequence'),scene_object_names=sorted(value.get('objects',{})),source_record=actor['process_record'],source_sha256=hashlib.sha256(path.read_bytes()).hexdigest())
        rows.append(row)
(A/'ordered-call-traces.json').write_text(json.dumps(rows,indent=2)+'\n')
with (A/'ordered-call-traces.csv').open('w',newline='') as f:
    w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader()
    for row in rows:w.writerow({k:json.dumps(v) if isinstance(v,(dict,list)) else v for k,v in row.items()})
example=[x for x in rows if x['condition']=='augmented_1' and x['layout_id']==4]
assert [x['call_id'] for x in example]==list(range(12))
assert example[-1]['method']=='approach' and not example[-1]['response_present']
case=dict(condition='augmented_1',layout_id=4,score_normalized=.15,success=False,ordered_calls=example,
 observation='First scene sequence1 contains watch_1 and one detected pen. After release, scene sequence943 contains two detected pens and no detected watch. The final attempted approach targets the right-side pen. Missing detections alone do not establish placement success; partial score comes from native receipts.',
 limitations=['Object labels are regenerated by category and X-sort each observation; they are not persistent track IDs.','Video review supports motion toward the watch and basket; exact score transition time and full object trajectory are not instrumented.','The second-object approach was unfinished at the native1100-step limit.','This live continuation does not validate every synthetic category-change case or prove a general recovery mechanism.'])
(A/'case-study-augmented1-layout4.json').write_text(json.dumps(case,indent=2)+'\n')
contrasts=[]
for i in range(1,4):
    for layout in range(5):
        pair=[next((a for a in d['actors'] if a['condition']==f'{prefix}_{i}' and a['mapping_qualified'] and a['mapped_layout_id']==layout),None) for prefix in ['baseline','augmented']]
        if any(a is None or not a['approach_targets'] for a in pair):continue
        b,a=[x['approach_targets'][0] for x in pair]
        contrasts.append(dict(candidate_pair=i,layout_id=layout,baseline_arm=b['arm'],augmented_arm=a['arm'],baseline_target_m=b['position_m'],augmented_target_m=a['position_m'],baseline_quaternion_wxyz=b['quaternion_wxyz'],augmented_quaternion_wxyz=a['quaternion_wxyz'],target_z_difference_m=a['position_m'][2]-b['position_m'][2],target_xy_distance_m=math.dist(a['position_m'][:2],b['position_m'][:2]),baseline_first_approach_rejected=pair[0]['first_approach_rejected'],augmented_first_approach_rejected=pair[1]['first_approach_rejected'],scope='Descriptive comparison of separately executed saved candidates; multiple variables and RGB estimates may differ; not a one-variable intervention'))
(A/'first-target-contrasts.json').write_text(json.dumps(contrasts,indent=2)+'\n')
if contrasts:
    with (A/'first-target-contrasts.csv').open('w',newline='') as f:
        w=csv.DictWriter(f,fieldnames=list(contrasts[0]));w.writeheader()
        for row in contrasts:w.writerow({k:json.dumps(v) if isinstance(v,(dict,list)) else v for k,v in row.items()})
print(json.dumps({'actors':len(d['actors']),'ordered_calls':len(rows),'case_study':'augmented_1/layout4'}))
